-- Backend Engineering ("The Fracture") Act 13 -- "NoSQL & Specialized Storage" content.
-- Closes Arc II (Data). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be13', 'world-be-13', 'nosql-and-specialized-storage', '13A - NoSQL & Specialized Storage', 'Every table Forge owns assumes rows, columns and foreign keys. Session cache, event logs, sensor readings and an identity graph never agreed to that shape -- and Arc II closes with finally getting each one into the store built for it.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be13-1', 'campaign-be13', 'foundations-of-nosql', 'Foundations of NoSQL', 'Why NoSQL exists, key-value stores, document databases, MongoDB concepts, and modelling data inside a document instead of across tables.', 1),
  ('operation-be13-2', 'campaign-be13', 'specialized-engines', 'Specialized Engines', 'Wide-column, graph and time-series concepts, Redis as a real data store, polyglot persistence, and choosing the right database on purpose.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be13-01', 'world-be-13', 'campaign-be13', 'operation-be13-1', 'why-nosql-exists', 'Why NoSQL Exists', 'Every table Forge owns assumes rows, columns, and a foreign key holding it together. Session cache, anomaly logs, sensor telemetry and an identity graph never agreed to that shape -- and forcing them into it is what''s draining the team right now.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"why-nosql-sim"}'::jsonb, '{"xp":195,"credits":35}'::jsonb, false, 1),
  ('mission-be13-02', 'world-be-13', 'campaign-be13', 'operation-be13-1', 'key-value-stores', 'Key-Value Stores', 'The simplest possible database: a key, a value, and nothing else guaranteed. That simplicity is exactly what makes it fast enough to fix the session cache problem.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be13-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"key-value-store-sim"}'::jsonb, '{"xp":197,"credits":35}'::jsonb, false, 2),
  ('mission-be13-03', 'world-be-13', 'campaign-be13', 'operation-be13-1', 'document-databases', 'Document Databases', 'A document database stores a whole object -- nested fields, arrays, all of it -- as one unit. The citizen profile that needed nine joined tables might need exactly one document.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be13-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"document-database-sim"}'::jsonb, '{"xp":199,"credits":36}'::jsonb, false, 3),
  ('mission-be13-04', 'world-be-13', 'campaign-be13', 'operation-be13-1', 'mongodb-concepts', 'MongoDB Concepts', 'MongoDB is the document database Forge actually runs. Collections instead of tables, documents instead of rows, and a query language shaped like the documents it queries.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be13-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"mongodb-concepts-sim"}'::jsonb, '{"xp":201,"credits":36}'::jsonb, false, 4),
  ('mission-be13-05', 'world-be-13', 'campaign-be13', 'operation-be13-1', 'data-modelling-in-documents', 'Data Modelling in Documents', 'A document model doesn''t remove the modeling decision, it just moves it: embed related data inside the parent, or reference it separately. Get it backwards and you feel it at read time or write time.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be13-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"document-data-modeling-sim"}'::jsonb, '{"xp":203,"credits":37}'::jsonb, false, 5),
  ('mission-be13-06', 'world-be-13', 'campaign-be13', 'operation-be13-1', 'wide-column-concepts', 'Wide-Column Concepts', 'Wide-column stores split data across nodes by a partition key and order it within that partition by a clustering key -- built for write-heavy workloads at a scale no single relational server can hold.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be13-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"wide-column-concepts-sim"}'::jsonb, '{"xp":205,"credits":37}'::jsonb, false, 6),
  ('mission-be13-07', 'world-be-13', 'campaign-be13', 'operation-be13-2', 'graph-database-concepts', 'Graph Database Concepts', 'The org chart -- who reports to whom -- keeps needing five-table joins to answer a one-hop question, and can''t answer a ten-hop question at all. A graph database stores the relationship itself as a first-class thing.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be13-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"graph-database-concepts-sim"}'::jsonb, '{"xp":207,"credits":38}'::jsonb, false, 7),
  ('mission-be13-08', 'world-be-13', 'campaign-be13', 'operation-be13-2', 'time-series-database-concepts', 'Time-Series Database Concepts', 'A sensor reporting once a second produces 86,400 rows a day, every day, forever. A relational table wasn''t built to ingest, compress and query that shape of data -- a time-series database was.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be13-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"time-series-concepts-sim"}'::jsonb, '{"xp":209,"credits":38}'::jsonb, false, 8),
  ('mission-be13-09', 'world-be-13', 'campaign-be13', 'operation-be13-2', 'redis-as-a-data-store', 'Redis as a Data Store', 'Redis is the key-value store behind the session cache -- and it does more than strings. Lists, sets, hashes and sorted sets turn "just a cache" into a real data structure server.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be13-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"redis-data-store-sim"}'::jsonb, '{"xp":211,"credits":39}'::jsonb, false, 9),
  ('mission-be13-10', 'world-be-13', 'campaign-be13', 'operation-be13-2', 'polyglot-persistence', 'Polyglot Persistence', 'No single database is right for every shape of data Forge owns. Polyglot persistence means running several, on purpose, and drawing a clear line at which one owns which data.', 'advanced', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be13-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"polyglot-persistence-sim"}'::jsonb, '{"xp":213,"credits":40}'::jsonb, false, 10),
  ('mission-be13-11', 'world-be-13', 'campaign-be13', 'operation-be13-2', 'choosing-the-right-database', 'Choosing the Right Database', 'Every store this Act taught solves a real problem and creates a real tradeoff. Choosing the right one means naming the access pattern first, and picking the store second -- never the other way around.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be13-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"choosing-the-right-database-sim"}'::jsonb, '{"xp":215,"credits":40}'::jsonb, false, 11),
  ('mission-be13-12', 'world-be-13', 'campaign-be13', 'operation-be13-2', 'one-database-for-everything', 'One Database for Everything', 'Five real datasets, five real access patterns, and the same mistake this whole Act started with waiting to happen again if you get even one of them wrong. Match every shape of data to the store that actually fits it -- and find out what that finally makes possible.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be13-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"one-database-for-everything-boss-sim"}'::jsonb, '{"xp":480,"credits":105,"badgeIds":["one-database-for-everything"],"skillXp":{"databases":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be13-01', 1, 'mira', 'Arc II closes here, and it opens with a mess: someone tried to force every shape of data we own into one relational schema. Session cache, anomaly logs, sensor telemetry, an identity graph -- all of it, into tables built for something else entirely.'),
  ('mission-be13-01', 2, 'forge', 'The transactions work made every table trustworthy. It didn''t make every table the right shape. Some of what we track was never rows and columns to begin with.'),
  ('mission-be13-01', 3, 'mira', 'This Act isn''t "relational databases are wrong." It''s "one tool, every job" that''s wrong. Learn what each shape of data actually wants, and Forge finally stops fighting its own storage.'),

  ('mission-be13-02', 1, 'forge', 'A key-value store makes exactly one promise: give it a key, it gives you back a value, as fast as physically possible. No joins, no schema to enforce, no query language to parse.'),
  ('mission-be13-02', 2, 'forge', 'That''s not a limitation, it''s the whole point. Session lookups don''t need a query planner. They need one hash lookup and an answer in microseconds.'),

  ('mission-be13-03', 1, 'mira', 'A document database stores a self-contained object -- nested fields, arrays, the works -- as a single unit, usually JSON or something close to it. No join required to read the whole thing back.'),
  ('mission-be13-03', 2, 'mira', 'That citizen profile spread across nine relational tables? In a document store it can be one document, one read, structure intact.'),

  ('mission-be13-04', 1, 'forge', 'MongoDB is the document store Forge actually runs in production. A collection is roughly a table. A document is roughly a row -- except every document in a collection can have a different shape.'),
  ('mission-be13-04', 2, 'forge', 'Every document gets an _id field automatically, unique within its collection -- the closest thing MongoDB has to a primary key.'),

  ('mission-be13-05', 1, 'mira', 'A document model doesn''t remove the modeling decision, it just moves it. Embed related data directly inside the parent document, or reference it by id and look it up separately -- every field needs that call made deliberately.'),
  ('mission-be13-05', 2, 'forge', 'Embed data that''s always read together and rarely changes independently. Reference data that grows without bound, or gets read and updated on its own.'),

  ('mission-be13-06', 1, 'forge', 'A wide-column store like Cassandra organizes data by a partition key -- which decides which node owns the data -- and a clustering key, which decides the order rows are stored within that partition.'),
  ('mission-be13-06', 2, 'forge', 'Query by partition key and it''s fast no matter how many nodes the data is spread across. Query by anything else and you''re asking every node to help, which is exactly what this model is built to avoid.'),

  ('mission-be13-07', 1, 'mira', 'A graph database stores nodes -- entities -- and edges -- the relationships between them -- as first-class things, not as foreign keys buried in a join table.'),
  ('mission-be13-07', 2, 'mira', '"Who does this person report to, five levels up" is a five-way self-join in a relational schema. In a graph, it''s a traversal -- walk the edges, stop when you run out.'),

  ('mission-be13-08', 1, 'forge', 'A time-series database assumes every row is a measurement at a timestamp, arriving in roughly chronological order, almost never updated once written.'),
  ('mission-be13-08', 2, 'forge', 'That assumption buys real things: compression tuned for sequences of similar numbers, and built-in downsampling, so "average temperature per hour, over the last year" doesn''t mean scanning a year of per-second rows.'),

  ('mission-be13-09', 1, 'mira', 'Redis is the key-value store behind the session cache -- but calling it "just a cache" undersells it. It''s a data structure server: strings, lists, sets, hashes, sorted sets, all held in memory with sub-millisecond access.'),
  ('mission-be13-09', 2, 'forge', 'Pick the wrong structure and you''ll reimplement one by hand on top of plain strings. Pick the right one and the operation you need is already built in.'),

  ('mission-be13-10', 1, 'forge', 'Six missions in, and the honest answer is Forge doesn''t need one database. It needs several, each one owning the shape of data it''s actually good at.'),
  ('mission-be13-10', 2, 'mira', 'That''s polyglot persistence -- Postgres for the ledger that needs transactions, Redis for the session cache, MongoDB for the citizen profile, a wide-column store for telemetry, a graph store for the org chart. On purpose, with a clear boundary around which system owns which data.'),

  ('mission-be13-11', 1, 'mira', 'Every store this Act taught was a genuine tradeoff, not a strictly better option. Relational buys strict consistency and joins at the cost of rigid schema. Document buys flexible shape at the cost of weaker cross-record guarantees. And so on, down the list.'),
  ('mission-be13-11', 2, 'mira', 'The question that actually matters isn''t "which database is best." It''s "what does this specific access pattern need" -- asked before a single line of schema gets written.'),

  ('mission-be13-12', 1, 'mira', 'Everything this Act taught points at one decision: match the shape of the data to the store actually built for it. Get it right five times in a row and something changes. Get it wrong once and Forge is back exactly where this Act started.'),
  ('mission-be13-12', 2, 'forge', 'Five real datasets, straight off what Forge actually runs: the session cache needing sub-millisecond reads, a citizen profile with deeply nested, variable structure, sensor telemetry arriving once a second, the org chart -- who reports to whom -- and a payment ledger that can never disagree with itself.'),
  ('mission-be13-12', 3, 'mira', 'Model every one of them correctly. No shortcuts, no "relational for everything because it''s familiar" -- that instinct is exactly what got us into this mess.'),
  ('mission-be13-12', 4, 'forge', 'Get this right and I want to try something I''ve never been able to run before: one query, across every storage engine Forge operates, for every occurrence of "//" logged anywhere, in any format -- one correlated timeline instead of five reports I''d have to eyeball together by hand.'),
  ('mission-be13-12', 5, 'mira', 'That actually resolved. First time this Arc we''ve seen the shape of what we''re chasing instead of one more isolated piece of it.'),
  ('mission-be13-12', 6, 'forge', 'I still can''t tell you what the pattern is, or who''s behind it. But for the first time, I can see every place it happens, at once. That''s not nothing.'),
  ('mission-be13-12', 7, 'mira', 'It''s not nothing. Arc II is closed -- the data is finally trustworthy, fast, and correlated. What Forge builds on top of it next is what other teams, other cities, actually consume. Starting with why REST alone stopped being enough for the mobile team.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be13-01-o1', 'mission-be13-01', 1, 'Diagnose the wrong fit', 'Find the evidence that explains why forcing this data into tables is the actual root cause, not just a symptom.'),
  ('mission-be13-02-o1', 'mission-be13-02', 1, 'Match the store to the property', 'Match each key-value store property to what it actually buys you.'),
  ('mission-be13-03-o1', 'mission-be13-03', 1, 'Sort the fit from the mismatch', 'Decide whether each dataset is a good fit for a document database.'),
  ('mission-be13-04-o1', 'mission-be13-04', 1, 'Match the vocabulary', 'Match each MongoDB term to its closest relational equivalent.'),
  ('mission-be13-04-o2', 'mission-be13-04', 2, 'Find the query bug', 'Debug a MongoDB filter that doesn''t match the documents it was meant to.'),
  ('mission-be13-05-o1', 'mission-be13-05', 1, 'Decide embed or reference', 'Decide whether each relationship should be embedded or referenced.'),
  ('mission-be13-05-o2', 'mission-be13-05', 2, 'Find the overembedding bug', 'Debug a document schema that embedded the wrong thing.'),
  ('mission-be13-06-o1', 'mission-be13-06', 1, 'Match the concept', 'Match each wide-column concept to what it actually controls.'),
  ('mission-be13-07-o1', 'mission-be13-07', 1, 'Order the traversal', 'Order the graph traversal steps for finding everyone within two reporting hops of a citizen.'),
  ('mission-be13-08-o1', 'mission-be13-08', 1, 'Diagnose the mismatch', 'Find the evidence that explains why the relational table is the wrong fit for sensor telemetry, not just overloaded by volume.'),
  ('mission-be13-09-o1', 'mission-be13-09', 1, 'Match the structure to the use case', 'Match each Redis data structure to the use case it fits best.'),
  ('mission-be13-09-o2', 'mission-be13-09', 2, 'Find the missing TTL', 'Debug the session cache code that never actually expires a session.'),
  ('mission-be13-10-o1', 'mission-be13-10', 1, 'Draw the ownership boundary', 'Find the evidence that shows a polyglot boundary that''s actually broken, not just unusual.'),
  ('mission-be13-11-o1', 'mission-be13-11', 1, 'Match the access pattern to the store', 'Match each described access pattern to the storage category built for it.'),
  ('mission-be13-12-o1', 'mission-be13-12', 1, 'Map every data shape', 'Match each of Forge''s five real datasets to the storage category actually built for its access pattern.'),
  ('mission-be13-12-o2', 'mission-be13-12', 2, 'Spot the store that would fail', 'Find the evidence that shows why one specific proposed mismatch would actually fail in practice.'),
  ('mission-be13-12-o3', 'mission-be13-12', 3, 'Confirm the boundary rule', 'Choose the one rule that should decide which store owns which dataset.'),
  ('mission-be13-12-o4', 'mission-be13-12', 4, 'Correlate the pattern', 'Synthesize the mapping into the payoff it was always building toward.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be13-01-o1-c1', 'mission-be13-01-o1', 1, 'investigation', 'Which evidence points at the actual root cause, not just one more symptom of it?', '{"evidence":[{"id":"ev1","label":"Session cache table","detail":"sessions table hit by 40,000 reads/sec, each one a single-row lookup by session_id, competing with every other query for the same connection pool"},{"id":"ev2","label":"Citizen profile table","detail":"citizen_profile joined across 9 normalized tables just to render one profile screen"},{"id":"ev3","label":"Schema note","detail":"Every one of these was modeled the same way: entities as rows, relationships as foreign keys, no matter what the actual access pattern looked like"}],"question":"Which evidence points at the actual root cause, not just one more symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be13-02-o1-c1', 'mission-be13-02-o1', 1, 'drag_and_drop', 'Match each key-value store property to what it actually buys you.', '{"items":[{"id":"p1","text":"O(1) lookup by key, no query planning"},{"id":"p2","text":"No fixed schema -- any value shape is allowed"},{"id":"p3","text":"No native support for querying by anything other than the key"},{"id":"p4","text":"Keys can be sharded across many nodes independently, since lookups never need to join across keys"}],"targets":[{"id":"t1","label":"Why it''s fast"},{"id":"t2","label":"Why it''s flexible"},{"id":"t3","label":"Its main limitation"},{"id":"t4","label":"Why it scales horizontally so easily"}]}'::jsonb, '{"correctMapping":{"p1":"t1","p2":"t2","p3":"t3","p4":"t4"}}'::jsonb),

  ('mission-be13-03-o1-c1', 'mission-be13-03-o1', 1, 'drag_and_drop', 'Decide whether each dataset is a good fit for a document database.', '{"items":[{"id":"i1","text":"A citizen profile with nested addresses, nested contact preferences, and a variable-length list of past permits"},{"id":"i2","text":"A ledger of financial transactions requiring strict multi-row consistency"},{"id":"i3","text":"A product catalog where each item has a different set of attributes"},{"id":"i4","text":"A many-to-many friendship graph queried by ''find everyone within 3 connections''"}],"targets":[{"id":"t1","label":"Good fit for a document database"},{"id":"t2","label":"Poor fit for a document database"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-be13-04-o1-c1', 'mission-be13-04-o1', 1, 'drag_and_drop', 'Match each MongoDB term to its closest relational equivalent.', '{"items":[{"id":"m1","text":"Collection"},{"id":"m2","text":"Document"},{"id":"m3","text":"_id"},{"id":"m4","text":"Embedded field"}],"targets":[{"id":"t1","label":"Roughly: a table"},{"id":"t2","label":"Roughly: a row"},{"id":"t3","label":"Roughly: a primary key"},{"id":"t4","label":"Has no clean relational equivalent -- a nested structure inside one row"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3","m4":"t4"}}'::jsonb),
  ('mission-be13-04-o2-c1', 'mission-be13-04-o2', 1, 'code_debugging', 'This filter is meant to find pending permits with priority greater than 3, but matches zero documents even though several exist. Which line contains the type mismatch?', '{"language":"json","code":"{\n  \"status\": \"pending\",\n  \"priority\": { \"$gt\": \"3\" }\n}","question":"This filter is meant to find pending permits with priority greater than 3, but matches zero documents even though several exist. Which line contains the type mismatch?"}'::jsonb, '{"requiredLineIds":["  \"priority\": { \"$gt\": \"3\" }"]}'::jsonb),

  ('mission-be13-05-o1-c1', 'mission-be13-05-o1', 1, 'drag_and_drop', 'Decide whether each relationship should be embedded or referenced.', '{"items":[{"id":"i1","text":"A citizen''s home address, read every time the profile loads and rarely changed"},{"id":"i2","text":"A citizen''s complete permit history, which can grow to thousands of entries over years"},{"id":"i3","text":"A blog post''s comments, which are added constantly and read independently of the post itself"},{"id":"i4","text":"A permit''s three-field status object, always read as part of the permit and never queried alone"}],"targets":[{"id":"t1","label":"Embed inside the parent document"},{"id":"t2","label":"Reference in a separate collection"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t2","i4":"t1"}}'::jsonb),
  ('mission-be13-05-o2-c1', 'mission-be13-05-o2', 1, 'code_debugging', 'This citizen document keeps hitting MongoDB''s 16MB document size limit and slows every profile read. Which line is responsible for the unbounded growth?', '{"language":"json","code":"{\n  \"citizenId\": \"C-4821\",\n  \"name\": \"R. Kwan\",\n  \"homeAddress\": { \"street\": \"12 Rowan St\", \"district\": 4 },\n  \"permitHistory\": [ \"3,400 embedded permit records and growing\" ]\n}","question":"This citizen document keeps hitting MongoDB''s 16MB document size limit and slows every profile read. Which line is responsible for the unbounded growth?"}'::jsonb, '{"requiredLineIds":["  \"permitHistory\": [ \"3,400 embedded permit records and growing\" ]"]}'::jsonb),

  ('mission-be13-06-o1-c1', 'mission-be13-06-o1', 1, 'drag_and_drop', 'Match each wide-column concept to what it actually controls.', '{"items":[{"id":"c1","text":"Partition key"},{"id":"c2","text":"Clustering key"},{"id":"c3","text":"Row"},{"id":"c4","text":"Column"}],"targets":[{"id":"t1","label":"Decides which node owns this data"},{"id":"t2","label":"Decides the sort order within one partition"},{"id":"t3","label":"One record, identified by its partition and clustering keys together"},{"id":"t4","label":"A single named field -- and different rows in the same table can have different sets of these"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t3","c4":"t4"}}'::jsonb),

  ('mission-be13-07-o1-c1', 'mission-be13-07-o1', 1, 'interactive_diagram', 'Order the graph traversal steps for finding everyone within two reporting hops of a citizen.', '{"diagramId":"graph-traversal-two-hops","hotspots":[{"id":"start_node","label":"Start at the citizen''s node","explanation":"The traversal always begins at a specific, known node -- there''s no table scan."},{"id":"one_hop","label":"Follow REPORTS_TO edges one hop","explanation":"Gather every node directly connected by the relationship, in either direction."},{"id":"two_hop","label":"Follow REPORTS_TO edges a second hop","explanation":"From each of those nodes, follow the same edge type again."},{"id":"collect","label":"Collect and de-duplicate the reached nodes","explanation":"Some nodes may be reachable by more than one path -- return each one once."}],"task":"Order the graph traversal steps for finding everyone within two reporting hops of a citizen."}'::jsonb, '{"correctOrderIds":["start_node","one_hop","two_hop","collect"]}'::jsonb),

  ('mission-be13-08-o1-c1', 'mission-be13-08-o1', 1, 'investigation', 'Which evidence explains why this is a modeling mismatch, not just a volume problem a bigger server would fix?', '{"evidence":[{"id":"ev1","label":"Row count","detail":"The sensor_readings table has 2.1 billion rows and is still growing by 86,400 rows per sensor per day"},{"id":"ev2","label":"Query pattern","detail":"Every dashboard query asks for an aggregate -- average, min, max -- over a time window, never a single row by primary key"},{"id":"ev3","label":"Storage note","detail":"The table consumes 340GB, mostly per-row column overhead for values that barely change between consecutive readings"}],"question":"Which evidence explains why this is a modeling mismatch, not just a volume problem a bigger server would fix?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be13-09-o1-c1', 'mission-be13-09-o1', 1, 'drag_and_drop', 'Match each Redis data structure to the use case it fits best.', '{"items":[{"id":"s1","text":"String"},{"id":"s2","text":"Hash"},{"id":"s3","text":"Sorted set"},{"id":"s4","text":"Set"}],"targets":[{"id":"t1","label":"A single session token mapped to one serialized value"},{"id":"t2","label":"A session''s multiple fields -- userId, expiresAt, role -- read and updated individually"},{"id":"t3","label":"A leaderboard, ranked by score, with fast ''top N'' and ''this user''s rank'' queries"},{"id":"t4","label":"A set of feature flags enabled for one citizen, with fast membership checks and no duplicates"}]}'::jsonb, '{"correctMapping":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb),
  ('mission-be13-09-o2-c1', 'mission-be13-09-o2', 1, 'code_debugging', 'This session cache never expires a session, even ones from citizens who logged out days ago. Which line is missing the piece that would fix that?', '{"language":"javascript","code":"async function createSession(sessionId, userData) {\n  const key = \"session:\" + sessionId;\n  await redis.set(key, JSON.stringify(userData));\n  return sessionId;\n}","question":"This session cache never expires a session, even ones from citizens who logged out days ago. Which line is missing the piece that would fix that?"}'::jsonb, '{"requiredLineIds":["  await redis.set(key, JSON.stringify(userData));"]}'::jsonb),

  ('mission-be13-10-o1-c1', 'mission-be13-10-o1', 1, 'investigation', 'Which evidence shows a polyglot boundary that''s actually broken, not just an example of the pattern working as intended?', '{"evidence":[{"id":"ev1","label":"Architecture note","detail":"Postgres owns the payment ledger, Redis owns session cache, MongoDB owns citizen profiles -- each system is the single source of truth for its own data"},{"id":"ev2","label":"Incident log","detail":"A citizen''s district value is written directly to both the MongoDB profile and a Postgres districts table, and the two now disagree after only one of them was updated"},{"id":"ev3","label":"Team habit","detail":"Engineers query Redis for session data and MongoDB for profile data, never crossing into each other''s collections directly"}],"question":"Which evidence shows a polyglot boundary that''s actually broken, not just an example of the pattern working as intended?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be13-11-o1-c1', 'mission-be13-11-o1', 1, 'drag_and_drop', 'Match each described access pattern to the storage category built for it.', '{"items":[{"id":"a1","text":"Sub-millisecond reads by a single known key, high throughput"},{"id":"a2","text":"A record with deeply nested, variably-shaped fields, read and written as one whole object"},{"id":"a3","text":"Multi-row writes that must all succeed or all fail together, with strict consistency"},{"id":"a4","text":"Queries that traverse relationships several hops deep"},{"id":"a5","text":"High-volume writes of timestamped measurements, queried mostly as aggregates over a window"}],"targets":[{"id":"t1","label":"Key-value store"},{"id":"t2","label":"Document database"},{"id":"t3","label":"Relational database"},{"id":"t4","label":"Graph database"},{"id":"t5","label":"Time-series database"}]}'::jsonb, '{"correctMapping":{"a1":"t1","a2":"t2","a3":"t3","a4":"t4","a5":"t5"}}'::jsonb),

  ('mission-be13-12-o1-c1', 'mission-be13-12-o1', 1, 'drag_and_drop', 'Match each of Forge''s five real datasets to the storage category actually built for its access pattern.', '{"items":[{"id":"d1","text":"Session cache: needs sub-millisecond reads by session id, high throughput, ok to lose on restart"},{"id":"d2","text":"Citizen profile: deeply nested addresses, preferences and a variable-length permit history, always read as one object"},{"id":"d3","text":"Sensor telemetry: one timestamped reading per second per sensor, queried almost always as an aggregate over a time window"},{"id":"d4","text":"Org chart: who reports to whom, queried by traversing reporting relationships several hops deep"},{"id":"d5","text":"Payment ledger: multi-row writes that must all succeed or all fail together, strict consistency required"}],"targets":[{"id":"t1","label":"Key-value store (Redis)"},{"id":"t2","label":"Document database"},{"id":"t3","label":"Time-series database"},{"id":"t4","label":"Graph database"},{"id":"t5","label":"Relational database"}]}'::jsonb, '{"correctMapping":{"d1":"t1","d2":"t2","d3":"t3","d4":"t4","d5":"t5"}}'::jsonb),
  ('mission-be13-12-o2-c1', 'mission-be13-12-o2', 1, 'investigation', 'Which evidence shows the actual mechanism behind why this specific proposal fails, not just the flawed reasoning that led to it?', '{"evidence":[{"id":"ev1","label":"Proposal","detail":"Store sensor telemetry in the same document database as citizen profiles, one document per sensor per day"},{"id":"ev2","label":"Load test result","detail":"That approach hits the document size limit within six hours of ingesting once-per-second readings, and every read pulls the whole day''s data just to compute one hour''s average"},{"id":"ev3","label":"Team note","detail":"Document databases are the most flexible option Forge runs, so the team assumed flexible meant universally applicable"}],"question":"Which evidence shows the actual mechanism behind why this specific proposal fails, not just the flawed reasoning that led to it?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be13-12-o3-c1', 'mission-be13-12-o3', 1, 'multiple_choice', 'The org chart and the payment ledger will both live outside the relational store you''d normally reach for by habit. What''s the one rule that decides where each dataset actually belongs?', '{"question":"The org chart and the payment ledger will both live outside the relational store you''d normally reach for by habit. What''s the one rule that decides where each dataset actually belongs?","options":[{"id":"a","text":"Whichever database the team is most comfortable with"},{"id":"b","text":"The access pattern the data is actually queried by -- key lookup, whole-object read, aggregate-over-time, traversal, or strict multi-row consistency -- decides the store, not familiarity or habit"},{"id":"c","text":"Always the newest database technology available"},{"id":"d","text":"Whichever store is cheapest to run"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be13-12-o4-c1', 'mission-be13-12-o4', 1, 'boss_encounter', 'Having modeled every dataset and confirmed the boundary, state what mapping every shape of data onto the right store just made possible for Forge.', '{"stages":[{"objectiveRef":"mission-be13-12-o1","label":"Map every data shape"},{"objectiveRef":"mission-be13-12-o2","label":"Spot the store that would fail"},{"objectiveRef":"mission-be13-12-o3","label":"Confirm the boundary rule"}],"task":"Having modeled every dataset and confirmed the boundary, state what mapping every shape of data onto the right store just made possible for Forge: a single correlated, queryable timeline of every \"//\" occurrence logged anywhere, across every storage engine Forge runs -- the first time Arc II''s recurring pattern has been visible as one shape instead of five separate fragments."}'::jsonb, '{"requiredObjectiveIds":["mission-be13-12-o1","mission-be13-12-o2","mission-be13-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be13-01-o1-c1', 'orientation', 'Two of these describe specific pain. One describes the decision that produced all of it.', 10, 1),
  ('mission-be13-01-o1-c1', 'concept', 'A single-row lookup by key and a nine-table join are solving completely different problems -- modeling them identically is the design choice, not an accident.', 20, 2),
  ('mission-be13-01-o1-c1', 'solution', 'ev3: every kind of data got the same relational treatment regardless of its actual access pattern -- that''s the root design decision the other two symptoms trace back to.', 30, 3),

  ('mission-be13-02-o1-c1', 'orientation', 'Fast, flexible, limited, scalable -- each property maps to a different one of those four words.', 10, 1),
  ('mission-be13-02-o1-c1', 'concept', 'Whatever makes joins impossible is also exactly what makes horizontal scaling and raw lookup speed so easy to get for free.', 20, 2),
  ('mission-be13-02-o1-c1', 'solution', 'p1 -> fast (O(1) lookup), p2 -> flexible (no schema), p3 -> limitation (key-only queries), p4 -> scales (shard by key, no cross-key joins to preserve).', 30, 3),

  ('mission-be13-03-o1-c1', 'orientation', 'Documents are great at "one self-contained object with a flexible shape." They''re not built for strict cross-row transactions or deep relationship traversal.', 10, 1),
  ('mission-be13-03-o1-c1', 'concept', 'Variable structure per record and nested data are exactly what a document model is for. Strict consistency across many rows, and graph traversal, are exactly what it isn''t.', 20, 2),
  ('mission-be13-03-o1-c1', 'solution', 'Good fit: the nested citizen profile, the variable-attribute product catalog. Poor fit: the strict-consistency ledger, the multi-hop friendship graph.', 30, 3),

  ('mission-be13-04-o1-c1', 'orientation', 'One of these terms doesn''t map to anything relational at all -- that''s deliberate.', 10, 1),
  ('mission-be13-04-o1-c1', 'concept', 'Three of these terms have a near-exact relational analog. The fourth is a structural feature relational schemas don''t really have.', 20, 2),
  ('mission-be13-04-o1-c1', 'solution', 'Collection -> table, document -> row, _id -> primary key, embedded field -> no clean equivalent (a nested object living inside one document).', 30, 3),
  ('mission-be13-04-o2-c1', 'orientation', 'Check each field''s value against what type the actual data stores.', 10, 1),
  ('mission-be13-04-o2-c1', 'concept', 'BSON is typed -- comparing a numeric field to a quoted string operand doesn''t coerce, it just fails to match anything.', 20, 2),
  ('mission-be13-04-o2-c1', 'solution', '"priority": { "$gt": "3" } compares a number field to a string operand -- it needs to be $gt: 3, unquoted, to actually match.', 30, 3),

  ('mission-be13-05-o1-c1', 'orientation', 'Ask two questions: does it grow without bound, and is it ever read or written on its own?', 10, 1),
  ('mission-be13-05-o1-c1', 'concept', 'Bounded, always-read-together data embeds cleanly. Unbounded or independently-accessed data belongs in its own collection, referenced by id.', 20, 2),
  ('mission-be13-05-o1-c1', 'solution', 'Embed: home address, permit status object. Reference: permit history (unbounded), comments (independent access).', 30, 3),
  ('mission-be13-05-o2-c1', 'orientation', 'Every field here is small and bounded except one.', 10, 1),
  ('mission-be13-05-o2-c1', 'concept', 'An array that keeps growing forever inside a single document eventually hits the document size limit and makes every read of that document heavier than it needs to be.', 20, 2),
  ('mission-be13-05-o2-c1', 'solution', 'permitHistory embeds an ever-growing list directly in the citizen document -- it should be its own collection, referenced by citizenId.', 30, 3),

  ('mission-be13-06-o1-c1', 'orientation', 'Two of these decide where data lives. Two of these describe the data itself.', 10, 1),
  ('mission-be13-06-o1-c1', 'concept', 'Partition key answers "which node." Clustering key answers "what order, once you''re on that node." Everything else follows from those two answers.', 20, 2),
  ('mission-be13-06-o1-c1', 'solution', 'Partition key -> which node owns it, clustering key -> sort order within the partition, row -> one record keyed by both, column -> a field that can vary row to row.', 30, 3),

  ('mission-be13-07-o1-c1', 'orientation', 'A traversal has to know where it starts before it can go anywhere.', 10, 1),
  ('mission-be13-07-o1-c1', 'concept', 'Each hop follows the same relationship type outward from wherever the previous hop landed -- and a node reached twice should still only count once.', 20, 2),
  ('mission-be13-07-o1-c1', 'solution', 'Start at the citizen''s node, follow the relationship one hop, follow it again for the second hop, then de-duplicate anything reached more than once.', 30, 3),

  ('mission-be13-08-o1-c1', 'orientation', 'A bigger server fixes volume. It doesn''t fix which questions the storage engine was optimized to answer.', 10, 1),
  ('mission-be13-08-o1-c1', 'concept', 'Every query here asks "aggregate over a time window," never "give me row X" -- that''s the exact shape a time-series engine optimizes for and a general-purpose row store doesn''t.', 20, 2),
  ('mission-be13-08-o1-c1', 'solution', 'ev2: the query pattern is always a time-windowed aggregate, never a point lookup -- that''s a modeling mismatch a bigger server wouldn''t fix, only a storage engine built for exactly that pattern would.', 30, 3),

  ('mission-be13-09-o1-c1', 'orientation', 'One structure holds one value. One holds named fields. One holds ranked scores. One holds unique membership.', 10, 1),
  ('mission-be13-09-o1-c1', 'concept', 'Match the shape of the question you''ll ask later -- "what''s the value," "what''s field X," "who''s in the top 10," "is this a member" -- to the structure built to answer it directly.', 20, 2),
  ('mission-be13-09-o1-c1', 'solution', 'String -> single session value, hash -> multiple named session fields, sorted set -> ranked leaderboard, set -> unique membership checks.', 30, 3),
  ('mission-be13-09-o2-c1', 'orientation', 'Redis keys live forever by default -- nothing expires a key unless something tells it to.', 10, 1),
  ('mission-be13-09-o2-c1', 'concept', 'SET without an expiry option (EX/PX) or a follow-up EXPIRE call creates a key with no TTL at all.', 20, 2),
  ('mission-be13-09-o2-c1', 'solution', 'redis.set(key, JSON.stringify(userData)) never sets an expiry -- it needs an EX (or PX) option, e.g. redis.set(key, JSON.stringify(userData), "EX", 3600), or the session lives forever.', 30, 3),

  ('mission-be13-10-o1-c1', 'orientation', 'Two of these describe the pattern working correctly. One describes the same fact stored in two places with nobody responsible for keeping them in sync.', 10, 1),
  ('mission-be13-10-o1-c1', 'concept', 'Polyglot persistence only works if each fact has exactly one owning system -- the moment the same value is writable in two places, you''ve recreated the "which one is true" problem NoSQL was supposed to help avoid.', 20, 2),
  ('mission-be13-10-o1-c1', 'solution', 'ev2: the same district value lives in two systems with no single owner, so of course they eventually disagree -- that''s a broken boundary, not evidence the pattern itself failed.', 30, 3),

  ('mission-be13-11-o1-c1', 'orientation', 'Match the verb in each description -- "lookup," "read as a whole object," "must all succeed together," "traverse," "aggregate over time" -- to the store built around that exact verb.', 10, 1),
  ('mission-be13-11-o1-c1', 'concept', 'None of these are about which database is "better" -- each is about which single access pattern the description is actually describing.', 20, 2),
  ('mission-be13-11-o1-c1', 'solution', 'Key lookup -> key-value. Nested whole-object read/write -> document. Multi-row strict consistency -> relational. Multi-hop relationships -> graph. Timestamped aggregates -> time-series.', 30, 3),

  ('mission-be13-12-o1-c1', 'orientation', 'Five datasets, five different verbs describing how each is actually queried -- match the verb, not the label.', 10, 1),
  ('mission-be13-12-o1-c1', 'solution', 'Session cache -> key-value (Redis), citizen profile -> document, sensor telemetry -> time-series, org chart -> graph, payment ledger -> relational.', 20, 2),
  ('mission-be13-12-o2-c1', 'orientation', 'The team''s reasoning is the symptom. The load test result is where the actual failure shows up.', 10, 1),
  ('mission-be13-12-o2-c1', 'solution', 'ev2: the load test shows the actual mechanism -- hitting the document size limit within hours and reading a whole day''s data to compute one hour''s aggregate. That''s the real failure, not just the flawed assumption that produced it.', 20, 2),
  ('mission-be13-12-o3-c1', 'orientation', 'Every correct match this mission had one thing in common as the deciding factor.', 10, 1),
  ('mission-be13-12-o3-c1', 'solution', 'b: the deciding factor is always the access pattern the data is actually queried by, never habit, familiarity, or which technology is newest.', 20, 2),
  ('mission-be13-12-o4-c1', 'orientation', 'Look at what correctly modeling all five datasets, together, finally made possible -- not any one of them in isolation.', 15, 1),
  ('mission-be13-12-o4-c1', 'solution', 'A single correlated, queryable timeline of every "//" occurrence logged anywhere, across every storage engine Forge runs -- Arc II''s pattern, visible whole for the first time instead of scattered across five separate systems.', 25, 2);
